Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
/*
@Date    : 2020-10-24 08:06:07
@Author  : Adscn (adscn@qq.com)
@Link    : https://www.cnblogs.com/LLCSBlog
*/
#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define IL inline
#define RG register
#define gi geti<int>()
#define gl geti<ll>()
#define gc getchar()
#define File(a) freopen(a".in","r",stdin);freopen(a".out","w",stdout)
template<typename T>IL bool chkmax(T &x,const T &y){return x<y?x=y,1:0;}
template<typename T>IL bool chkmin(T &x,const T &y){return x>y?x=y,1:0;}
template<typename T>
IL T geti()
{
	RG T xi=0;
	RG char ch=gc;
	bool f=0;
	while(!isdigit(ch))ch=='-'?f=1:f,ch=gc;
	while(isdigit(ch))xi=xi*10+ch-48,ch=gc;
	return f?-xi:xi;
}
template<typename T>
IL void pi(T k,char ch=0)
{
	if(k<0)k=-k,putchar('-');
	if(k>=10)pi(k/10);
	putchar(k%10+'0');
	if(ch)putchar(ch);
}
const int N=3e5+10;
int P=1e9+9;
int f[19][N];
int ifac[N],fac[N],inv[N];
inline ll fpow(ll a,int b,ll c=1){
	for(;b;b>>=1,a=a*a%P)if(b&1)c=c*a%P;
	return c;
}
inline void init(int n){
	fac[0]=1;
	for(int i=1;i<=n;++i)fac[i]=1ll*fac[i-1]*i%P;
	ifac[n]=fpow(fac[n],P-2);
	for(int i=n-1;~i;--i)ifac[i]=ifac[i+1]*(i+1ll)%P;
	inv[1]=1;
	for(int i=2;i<=n;++i)inv[i]=1ll*(P-P/i)*inv[P%i]%P;
}
inline void add(int &x,int y){x+=y;if(x>=P)x-=P;}
inline void sub(int &x,int y){x-=y;x-=(x>>31)*P;}
inline int sub(int x){return x-(x>>31)*P;}
int t[20],g[20];
inline void fpow(int *f,int n,int k){
	memcpy(t,f,4*n+4);
	f[0]=1-f[0],g[0]=0;
	for(int i=1;i<n;++i)
	{
		f[i]=g[i]=0;
		for(int j=1;j<i;++j)
			f[i]=(f[i]+1ll*f[i-j]*g[j])%P,
			g[i]=(g[i]+1ll*t[i-j]*g[j])%P;
		sub(f[i],g[i]);
		f[i]=(t[i]+1ll*f[i]*inv[i])%P*k%P,
		g[i]=(t[i]-1ll*g[i]*inv[i])%P*i%P;
	}
}
inline void FMT(int *f,int n)
{
	for(int l=1;l<n;l<<=1)
		for(int i=0;i<n;i+=l<<1)
			for(RG int j=0;j<l;++j)
				add(f[i+j+l],f[i+j]);
}
inline void IFMT(int *f,int n)
{
	for(int l=1;l<n;l<<=1)
		for(int i=0;i<n;i+=l<<1)
			for(RG int j=0;j<l;++j)
				sub(f[i+j+l],f[i+j]);
}
int n,k;
#define pop(x) __builtin_popcount(x)
int main(void)
{
	n=gi,k=gi;P=gi;
	int ans=fpow(k,n);
	if(~n&1){
		int m=(int)log2(n)+1;
		init(1<<m);
		for(int i=0;i<(1<<m);++i)f[pop(i)][i]=ifac[i];
		for(int i=0;i<=m;++i)FMT(f[i],1<<m);
		static int F[20];
		for(int i=0;i<=n;++i){
			for(int j=0;j<=m;++j)F[j]=f[j][i];
			fpow(F,m+1,k);
			for(int j=0;j<=m;++j)f[j][i]=F[j];
		}
		IFMT(f[pop(n)],1<<m);
		ans=(P+ans-1ll*f[pop(n)][n]*fac[n]%P)%P;
	}
	pi(ans);
	return 0;
}
